@lru_cache(maxsize=1)
def game_html() -> str:
    assets = json.loads(gzip.decompress(base64.b64decode(_BUNDLE)))
    page = assets.pop("index.html")
    style = assets.pop("style.css")
    page = re.sub(r'<link rel="stylesheet"[^>]*>', '', page)
    page = re.sub(r'<link rel="icon"[^>]*>', '', page)
    page = re.sub(r'<script type="module"[^>]*></script>', '', page)
    style += "\nmain{padding:12px 14px}.arena{height:560px;min-height:300px}header{margin-bottom:10px}footer{margin-top:10px}@media(max-width:650px){main{padding:8px}.arena{height:530px}}"
    page = page.replace('</head>', '<style>' + style + '</style></head>')
    # Protect the enclosing HTML script while keeping JS strings intact.
    data = json.dumps(assets, ensure_ascii=False).replace('<', '\u003c')
    bootstrap = r"""
<script type="module">
const assets=__ASSETS__;
const moduleURL=source=>URL.createObjectURL(new Blob([source],{type:'text/javascript'}));
try{
 window.__SABER_AUDIO__=Object.fromEntries(Object.entries(assets.audio).map(([name,data])=>{
  const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));
  return [name,URL.createObjectURL(new Blob([bytes],{type:'audio/wav'}))];
 }));
 const coreURL=moduleURL(assets['three.core.js']);
 const threeURL=moduleURL(assets['three.module.js'].replaceAll('./three.core.js',coreURL));
 const combatURL=moduleURL(assets['combat.js']);
 const audioSource=assets['saber-audio.js'].replace('new URL(`./audio/${name}.wav`,import.meta.url)','window.__SABER_AUDIO__[name]');
 const audioURL=moduleURL(audioSource);
 let gameSource=assets['game.js']
  .replace(/\.\/three\.module\.js/g,threeURL)
  .replace(/\.\/combat\.js\?v=\d+/g,combatURL)
  .replace(/\.\/saber-audio\.js\?v=\d+/g,audioURL);
 document.body.tabIndex=0;
 document.addEventListener('pointerdown',()=>window.focus(),{capture:true});
 await import(moduleURL(gameSource));
}catch(error){
 const message=document.getElementById('error');message.hidden=false;
 message.textContent='ゲームを開始できませんでした。WebGL対応のChrome/Safariで再読み込みしてください。'+error.message;
 document.getElementById('loadStatus').textContent='開始できませんでした';
}
</script>
""".replace('__ASSETS__',data)
    return page.replace('</body>',bootstrap+'</body>')


def main() -> None:
    import streamlit as st
    st.set_page_config(page_title='LIGHTSABER SWORDMASTER', page_icon='⚔️', layout='wide')
    st.markdown('<style>.block-container{padding-top:1rem;padding-bottom:1rem;max-width:1500px}iframe{border:0}</style>', unsafe_allow_html=True)
    st.caption('COM同士が自動対戦。「自分で操作する」で切替：A＝防御（長押し） / D＝攻撃（長押し） / F＝懸 / S＝カウンター（長押し）。矢印キーで移動。音はゲーム内の「音 OFF」で有効にできます。')
    if hasattr(st, 'iframe'):
        st.iframe(game_html(), height=860, tab_index=0)
    else:
        import streamlit.components.v1 as components
        components.html(game_html(), height=860, scrolling=True)


if __name__ == '__main__':
    main()
